1	package harnesses
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7	)
8	
9	const (
10		UsageSourceNativeStream     = "native_stream"
11		UsageSourceNativeTokenCount = "native_token_count" // #nosec G101 -- usage source identifier, not a credential.
12		UsageSourceTranscript       = "transcript"
13		UsageSourceStatusOutput     = "status_output"
14		UsageSourceFallback         = "fallback"
15	
16		UsageWarningMalformed    = "usage_malformed"
17		UsageWarningDisagreement = "usage_source_disagreement"
18	)
19	
20	// UsageCandidate is one candidate source considered for final token usage.
21	type UsageCandidate struct {
22		Source     string
23		Fresh      *bool
24		CapturedAt string
25		Counts     UsageTokenCounts
26		Warning    string
27	}
28	
29	// ResolveFinalUsage applies the documented source precedence:
30	// native_stream > transcript > status_output > fallback. It returns nil usage
31	// when no source reported a token count, while still returning warnings for
32	// malformed sources or source disagreements.
33	func ResolveFinalUsage(candidates []UsageCandidate) (*FinalUsage, []FinalWarning) {
34		if len(candidates) == 0 {
35			return nil, nil
36		}
37		ordered := append([]UsageCandidate(nil), candidates...)
38		sort.SliceStable(ordered, func(i, j int) bool {
39			return usageSourceRank(ordered[i].Source) < usageSourceRank(ordered[j].Source)
40		})
41	
42		var warnings []FinalWarning
43		var valid []UsageCandidate
44		validBySource := map[string]int{}
45		for _, candidate := range ordered {
46			if candidate.Counts.Any() {
47				if idx, ok := validBySource[candidate.Source]; ok {
48					valid[idx] = candidate
49				} else {
50					validBySource[candidate.Source] = len(valid)
51					valid = append(valid, candidate)
52				}
53			}
54			if candidate.Warning != "" {
55				warnings = append(warnings, FinalWarning{
56					Code:    UsageWarningMalformed,
57					Message: candidate.Warning,
58					Sources: []UsageSourceEvidence{
59						usageEvidence(candidate),
60					},
61				})
62			}
63		}
64		if len(valid) == 0 {
65			return nil, warnings
66		}
67	
68		chosen := valid[0]
69		for i := 1; i < len(valid); i++ {
70			if usageCountsDisagree(chosen.Counts, valid[i].Counts) {
71				warnings = append(warnings, FinalWarning{
72					Code:    UsageWarningDisagreement,
73					Message: "token usage sources disagree; selected source by documented precedence",
74					Sources: []UsageSourceEvidence{
75						usageEvidence(chosen),
76						usageEvidence(valid[i]),
77					},
78				})
79			}
80		}
81	
82		usage := &FinalUsage{
83			InputTokens:      chosen.Counts.InputTokens,
84			OutputTokens:     chosen.Counts.OutputTokens,
85			CacheReadTokens:  chosen.Counts.CacheReadTokens,
86			CacheWriteTokens: chosen.Counts.CacheWriteTokens,
87			CacheTokens:      chosen.Counts.CacheTokens,
88			ReasoningTokens:  chosen.Counts.ReasoningTokens,
89			TotalTokens:      chosen.Counts.TotalTokens,
90			Source:           chosen.Source,
91			Fresh:            chosen.Fresh,
92			CapturedAt:       chosen.CapturedAt,
93			Sources:          make([]UsageSourceEvidence, 0, len(valid)),
94		}
95		for _, candidate := range valid {
96			usage.Sources = append(usage.Sources, usageEvidence(candidate))
97		}
98		return usage, warnings
99	}
100	
101	func usageSourceRank(source string) int {
102		switch source {
103		case UsageSourceNativeStream:
104			return 0
105		case UsageSourceNativeTokenCount:
106			return 1
107		case UsageSourceTranscript:
108			return 2
109		case UsageSourceStatusOutput:
110			return 3
111		case UsageSourceFallback:
112			return 4
113		default:
114			return 100
115		}
116	}
117	
118	func usageEvidence(candidate UsageCandidate) UsageSourceEvidence {
119		counts := candidate.Counts
120		var usage *UsageTokenCounts
121		if counts.Any() {
122			usage = &counts
123		}
124		return UsageSourceEvidence{
125			Source:     candidate.Source,
126			Fresh:      candidate.Fresh,
127			CapturedAt: candidate.CapturedAt,
128			Usage:      usage,
129			Warning:    candidate.Warning,
130		}
131	}
132	
133	func usageCountsDisagree(a, b UsageTokenCounts) bool {
134		return ptrIntDisagree(a.InputTokens, b.InputTokens) ||
135			ptrIntDisagree(a.OutputTokens, b.OutputTokens) ||
136			ptrIntDisagree(a.CacheReadTokens, b.CacheReadTokens) ||
137			ptrIntDisagree(a.CacheWriteTokens, b.CacheWriteTokens) ||
138			ptrIntDisagree(a.CacheTokens, b.CacheTokens) ||
139			ptrIntDisagree(a.ReasoningTokens, b.ReasoningTokens) ||
140			ptrIntDisagree(a.TotalTokens, b.TotalTokens)
141	}
142	
143	func ptrIntDisagree(a, b *int) bool {
144		return a != nil && b != nil && *a != *b
145	}
