147	// ParseUsageJSON normalizes common Claude/Codex/OpenAI-style usage objects.
148	// Unknown dimensions remain nil. A present zero remains present.
149	func ParseUsageJSON(raw json.RawMessage) (UsageTokenCounts, error) {
150		var counts UsageTokenCounts
151		if len(raw) == 0 || string(raw) == "null" {
152			return counts, nil
153		}
154		var obj map[string]json.RawMessage
155		if err := json.Unmarshal(raw, &obj); err != nil {
156			return counts, fmt.Errorf("usage object is not JSON: %w", err)
157		}
158		if obj == nil {
159			return counts, nil
160		}
161	
162		var err error
163		if counts.InputTokens, err = firstInt(obj, "input_tokens", "prompt_tokens", "input"); err != nil {
164			return counts, err
165		}
166		if counts.OutputTokens, err = firstInt(obj, "output_tokens", "completion_tokens", "output"); err != nil {
167			return counts, err
168		}
169		if counts.CacheReadTokens, err = firstInt(obj, "cache_read_input_tokens", "cache_read_tokens", "cached_input_tokens"); err != nil {
170			return counts, err
171		}
172		if counts.CacheWriteTokens, err = firstInt(obj, "cache_creation_input_tokens", "cache_write_tokens"); err != nil {
173			return counts, err
174		}
175		if counts.CacheTokens, err = firstInt(obj, "cache_tokens", "cached_tokens"); err != nil {
176			return counts, err
177		}
178		if counts.ReasoningTokens, err = firstInt(obj, "reasoning_tokens", "reasoning_output_tokens"); err != nil {
179			return counts, err
180		}
181		if counts.TotalTokens, err = firstInt(obj, "total_tokens", "total"); err != nil {
182			return counts, err
183		}
184	
185		if details, ok := rawObject(obj, "prompt_tokens_details"); ok && counts.CacheReadTokens == nil {
186			if counts.CacheReadTokens, err = firstInt(details, "cached_tokens"); err != nil {
187				return counts, err
188			}
189		}
190		if details, ok := rawObject(obj, "completion_tokens_details"); ok && counts.ReasoningTokens == nil {
191			if counts.ReasoningTokens, err = firstInt(details, "reasoning_tokens"); err != nil {
192				return counts, err
193			}
194		}
195		if details, ok := rawObject(obj, "output_tokens_details"); ok && counts.ReasoningTokens == nil {
196			if counts.ReasoningTokens, err = firstInt(details, "reasoning_tokens"); err != nil {
197				return counts, err
198			}
199		}
200	
201		if counts.TotalTokens == nil && counts.InputTokens != nil && counts.OutputTokens != nil {
202			total := *counts.InputTokens + *counts.OutputTokens
203			counts.TotalTokens = &total
204		}
205		if counts.CacheTokens == nil && (counts.CacheReadTokens != nil || counts.CacheWriteTokens != nil) {
206			total := 0
207			if counts.CacheReadTokens != nil {
208				total += *counts.CacheReadTokens
209			}
210			if counts.CacheWriteTokens != nil {
211				total += *counts.CacheWriteTokens
212			}
213			counts.CacheTokens = &total
214		}
215		return counts, nil
216	}
