218	func firstInt(obj map[string]json.RawMessage, names ...string) (*int, error) {
219		for _, name := range names {
220			raw, ok := obj[name]
221			if !ok {
222				continue
223			}
224			var n int
225			if err := json.Unmarshal(raw, &n); err == nil {
226				return &n, nil
227			}
228			var f float64
229			if err := json.Unmarshal(raw, &f); err == nil {
230				n = int(f)
231				return &n, nil
232			}
233			return nil, fmt.Errorf("usage field %q is not numeric", name)
234		}
235		return nil, nil
236	}
237	
238	func rawObject(obj map[string]json.RawMessage, name string) (map[string]json.RawMessage, bool) {
239		raw, ok := obj[name]
240		if !ok {
241			return nil, false
242		}
243		var nested map[string]json.RawMessage
244		if err := json.Unmarshal(raw, &nested); err != nil {
245			return nil, false
246		}
247		return nested, true
248	}
