1	package claude
2	
3	import (
4		"bufio"
5		"context"
6		"encoding/json"
7		"errors"
8		"io"
9		"strings"
10		"time"
11	
12		"github.com/easel/fizeau/internal/harnesses"
13	)
14	
15	// claudeStreamEvent is a minimal, lenient view of a claude CLI stream-json
16	// event. Only the fields we need for progress and final result are decoded.
17	type claudeStreamEvent struct {
18		Type    string          `json:"type"`
19		Subtype string          `json:"subtype"`
20		Message json.RawMessage `json:"message"`
21		Result  string          `json:"result"`
22		Source  string          `json:"source"`
23		Fresh   *bool           `json:"fresh"`
24	
25		// result-event fields
26		Usage           json.RawMessage `json:"usage"`
27		CapturedAt      string          `json:"captured_at"`
28		TotalCostUSD    float64         `json:"total_cost_usd"`
29		DurationMsField int64           `json:"duration_ms"`
30		SessionID       string          `json:"session_id"`
31		IsError         bool            `json:"is_error"`
32	
33		// system/init fields
34		Model string `json:"model"`
35	}
36	
37	// claudeAssistantMessage is the shape of the "message" field in an
38	// {"type":"assistant",...} stream-json event. It is Claude's native
39	// Messages API payload.
40	type claudeAssistantMessage struct {
41		ID      string               `json:"id"`
42		Model   string               `json:"model"`
43		Content []claudeMessageBlock `json:"content"`
44		Usage   json.RawMessage      `json:"usage"`
45		Stop    string               `json:"stop_reason,omitempty"`
46	}
47	
48	type claudeMessageBlock struct {
49		Type      string          `json:"type"`
50		Text      string          `json:"text,omitempty"`
51		ID        string          `json:"id,omitempty"`
52		Name      string          `json:"name,omitempty"`
53		Input     json.RawMessage `json:"input,omitempty"`
54		ToolUseID string          `json:"tool_use_id,omitempty"`
55		Content   json.RawMessage `json:"content,omitempty"`
56		IsError   bool            `json:"is_error,omitempty"`
57	}
58	
59	// claudeUserMessage is the shape of the "message" field in a
60	// {"type":"user",...} stream-json event, which carries tool_result content.
61	type claudeUserMessage struct {
62		Content []claudeMessageBlock `json:"content"`
63	}
64	
65	// streamAggregate captures running totals exposed by the claude stream so
66	// the runner can attach final-event usage/cost without re-parsing.
67	type streamAggregate struct {
68		FinalText    string
69		SessionID    string
70		Model        string
71		UsageSources []harnesses.UsageCandidate
72		Warnings     []harnesses.FinalWarning
73		CostUSD      float64
74		ToolCalls    int
75		TurnCount    int
76		IsError      bool
77	}
78	
79	// parseClaudeStream reads newline-delimited claude stream-json events from r
80	// and emits harness Events on out. Each parsed claude event maps to zero or
81	// more harness Events per CONTRACT-003 §"Event JSON shapes":
82	//
83	//   - claude system/init        -> (no event; recorded into aggregate.Model/SessionID)
84	//   - claude assistant text     -> EventTypeTextDelta
85	//   - claude assistant tool_use -> EventTypeToolCall
86	//   - claude user tool_result   -> EventTypeToolResult
87	//   - claude result             -> (no event; aggregate populated with usage/cost)
88	//
89	// metadata is copied onto every emitted Event. seq starts at 0 and is
90	// incremented per event so callers can reconstruct ordering.
91	//
92	// parseClaudeStream returns the aggregated stream state; callers use it to
93	// build a synthetic final event.
94	//
95	// out is NOT closed; the caller owns the channel and is responsible for
96	// closing once the final event has been emitted.
97	//
98	// ctx is honored: when ctx is done the parser returns early with the
99	// running aggregate and ctx.Err().
100	func parseClaudeStream(ctx context.Context, r io.Reader, out chan<- harnesses.Event, metadata map[string]string, seq *int64) (*streamAggregate, error) {
101		agg := &streamAggregate{}
102		scanner := bufio.NewScanner(r)
103		scanner.Buffer(make([]byte, 0, 256*1024), 16*1024*1024) // 16MB max line — claude can dump big tool results
104	
105		emit := func(t harnesses.EventType, data any) error {
106			raw, err := json.Marshal(data)
107			if err != nil {
108				return err
109			}
110			ev := harnesses.Event{
111				Type:     t,
112				Sequence: *seq,
113				Time:     time.Now().UTC(),
114				Metadata: metadata,
115				Data:     raw,
116			}
117			*seq++
118			select {
119			case out <- ev:
120				return nil
121			case <-ctx.Done():
122				return ctx.Err()
123			}
124		}
125	
126		for scanner.Scan() {
127			// Honor cancellation between lines too.
128			select {
129			case <-ctx.Done():
130				return agg, ctx.Err()
131			default:
132			}
133	
134			line := strings.TrimSpace(scanner.Text())
135			if line == "" {
136				continue
137			}
138			var ev claudeStreamEvent
139			if err := json.Unmarshal([]byte(line), &ev); err != nil {
140				// Not a JSON event — skip silently to be lenient. Matches the DDx
141				// parser behavior so partial / corrupted lines don't kill the run.
142				continue
143			}
144	
145			switch ev.Type {
146			case "system":
147				if ev.Subtype == "init" {
148					if ev.Model != "" {
149						agg.Model = ev.Model
150					}
151					if ev.SessionID != "" {
152						agg.SessionID = ev.SessionID
153					}
154				}
155	
156			case "assistant":
157				var msg claudeAssistantMessage
158				if len(ev.Message) > 0 {
159					_ = json.Unmarshal(ev.Message, &msg)
160				}
161				if msg.Model != "" && agg.Model == "" {
162					agg.Model = msg.Model
163				}
164				agg.recordUsage(msg.Usage)
165				agg.TurnCount++
166	
167				for _, block := range msg.Content {
168					switch block.Type {
169					case "text":
170						if block.Text == "" {
171							continue
172						}
173						if err := emit(harnesses.EventTypeTextDelta, harnesses.TextDeltaData{Text: block.Text}); err != nil {
174							return agg, err
175						}
176						// Track the most recent text content so a missing
177						// result event still leaves us with output text.
178						agg.FinalText = block.Text
179					case "tool_use":
180						name := block.Name
181						if name == "" {
182							name = "tool"
183						}
184						agg.ToolCalls++
185						if err := emit(harnesses.EventTypeToolCall, harnesses.ToolCallData{
186							ID:    block.ID,
187							Name:  name,
188							Input: block.Input,
189						}); err != nil {
190							return agg, err
191						}
192					}
193				}
194	
195			case "user":
196				// User messages carry tool_result content blocks.
197				var msg claudeUserMessage
198				if len(ev.Message) > 0 {
199					_ = json.Unmarshal(ev.Message, &msg)
200				}
201				for _, block := range msg.Content {
202					if block.Type != "tool_result" {
203						continue
204					}
205					output := decodeToolResultContent(block.Content)
206					data := harnesses.ToolResultData{
207						ID:     block.ToolUseID,
208						Output: output,
209					}
210					if block.IsError {
211						data.Error = output
212						data.Output = ""
213					}
214					if err := emit(harnesses.EventTypeToolResult, data); err != nil {
215						return agg, err
216					}
217				}
218	
219			case "result":
220				if ev.Result != "" {
221					agg.FinalText = ev.Result
222				}
223				agg.recordUsage(ev.Usage)
224				if ev.TotalCostUSD > 0 {
225					agg.CostUSD = ev.TotalCostUSD
226				}
227				if ev.SessionID != "" {
228					agg.SessionID = ev.SessionID
229				}
230				if ev.IsError {
231					agg.IsError = true
232				}
233			case "ddx.usage_source":
234				agg.recordUsageSource(ev.Source, ev.Fresh, ev.CapturedAt, ev.Usage)
235			}
236		}
237		if err := scanner.Err(); err != nil && !errors.Is(err, io.EOF) {
238			return agg, err
239		}
240		return agg, nil
241	}
242	
243	func (a *streamAggregate) recordUsage(raw json.RawMessage) {
244		a.recordUsageSource(harnesses.UsageSourceNativeStream, harnesses.BoolPtr(true), "", raw)
245	}
246	
247	func (a *streamAggregate) recordUsageSource(source string, fresh *bool, capturedAt string, raw json.RawMessage) {
248		if len(raw) == 0 || string(raw) == "null" {
249			return
250		}
251		if source == "" {
252			source = harnesses.UsageSourceFallback
253		}
254		counts, err := harnesses.ParseUsageJSON(raw)
255		if err != nil {
256			a.UsageSources = append(a.UsageSources, harnesses.UsageCandidate{
257				Source:     source,
258				Fresh:      fresh,
259				CapturedAt: capturedAt,
260				Warning:    err.Error(),
261			})
262			return
263		}
264		if counts.Any() {
265			a.UsageSources = append(a.UsageSources, harnesses.UsageCandidate{
266				Source:     source,
267				Fresh:      fresh,
268				CapturedAt: capturedAt,
269				Counts:     counts,
270			})
271		}
272	}
273	
274	// decodeToolResultContent normalises the variable shapes claude uses for
275	// tool_result content. The CLI may emit either a plain string or an array
276	// of content blocks; we collapse both to a single string so the harness
277	// Event payload stays simple.
278	func decodeToolResultContent(raw json.RawMessage) string {
279		if len(raw) == 0 {
280			return ""
281		}
282		// Try string first.
283		var s string
284		if err := json.Unmarshal(raw, &s); err == nil {
285			return s
286		}
287		// Then an array of blocks like [{"type":"text","text":"..."}].
288		var blocks []claudeMessageBlock
289		if err := json.Unmarshal(raw, &blocks); err == nil {
290			var sb strings.Builder
291			for i, b := range blocks {
292				if b.Type == "text" && b.Text != "" {
293					if i > 0 && sb.Len() > 0 {
294						sb.WriteString("\n")
295					}
296					sb.WriteString(b.Text)
297				}
298			}
299			return sb.String()
300		}

1	// Package openaicompat contains shared OpenAI-compatible Chat Completions
2	// protocol plumbing. Provider identity, cost attribution, routing, and
3	// provider-specific discovery live in provider packages above this layer.
4	package openaicompat
5	
6	import (
7		"context"
8		"encoding/json"
9		"net"
10		"net/http"
11		"strings"
12		"time"
13	
14		agent "github.com/easel/fizeau/internal/core"
15		"github.com/easel/fizeau/internal/provider/quotaheaders"
16		oai "github.com/openai/openai-go"
17		"github.com/openai/openai-go/option"
18		"github.com/openai/openai-go/packages/param"
19	)
20	
21	// DefaultConnectTimeout bounds the TCP connect phase of every request issued
22	// by the OpenAI-compatible client. Go's net/http default Transport uses a
23	// zero-value net.Dialer with no Timeout, which on Linux waits for the kernel's
24	// full SYN-retransmit window (~30s) before surfacing a dial-class failure.
25	// A dead local endpoint is a routing input — not a slow upstream — so the
26	// connect phase is bounded independently of the request-streaming timeout.
27	const DefaultConnectTimeout = 5 * time.Second
28	
29	// Config contains the protocol/client settings shared by providers that speak
30	// the OpenAI-compatible Chat Completions API.
31	type Config struct {
32		BaseURL string
33		APIKey  string
34		Headers map[string]string
35		// QuotaHeaderParser, when set, is called on every response to convert
36		// the response Header into a quotaheaders.Signal. The signal is then
37		// forwarded to QuotaSignalObserver. Different providers (OpenAI vs
38		// OpenRouter) use different parsers, so the protocol layer takes the
39		// parser as a function and stays provider-agnostic.
40		QuotaHeaderParser func(http.Header, time.Time) quotaheaders.Signal
41		// QuotaSignalObserver, when set together with QuotaHeaderParser, receives
42		// the parsed signal on every response. The service layer wires this to
43		// the provider quota state machine.
44		QuotaSignalObserver func(quotaheaders.Signal)
45		// RuntimeSignalObserver, when set, receives the raw response headers,
46		// request latency, and any terminal error for every provider response.
47		RuntimeSignalObserver func(http.Header, time.Duration, error)
48		// ConnectTimeout bounds the TCP connect phase (dial) for every request.
49		// Zero or negative values fall back to DefaultConnectTimeout (5s). The
50		// request-streaming timeout is intentionally not bounded here: large
51		// completions legitimately take minutes once the connection is established.
52		ConnectTimeout time.Duration
53	}
54	
55	// Client wraps openai-go with agent-native request and response conversion.
56	type Client struct {
57		client         *oai.Client
58		connectTimeout time.Duration
59	}
60	
61	// NewClient creates an OpenAI-compatible protocol client.
62	func NewClient(cfg Config) *Client {
63		connectTimeout := cfg.ConnectTimeout
64		if connectTimeout <= 0 {
65			connectTimeout = DefaultConnectTimeout
66		}
67		httpClient := newHTTPClient(connectTimeout)
68		opts := []option.RequestOption{
69			option.WithBaseURL(cfg.BaseURL),
70			option.WithMaxRetries(0),
71			option.WithHTTPClient(httpClient),
72		}
73		if cfg.APIKey != "" {
74			opts = append(opts, option.WithAPIKey(cfg.APIKey))
75		} else {
76			opts = append(opts, option.WithAPIKey("not-needed"))
77		}
78		for k, v := range cfg.Headers {
79			opts = append(opts, option.WithHeader(k, v))
80		}
81		// SSE comment-frame filter must sit before the debug sink so the sink
82		// observes the same byte stream the decoder will see. Middlewares are
83		// applied in registration order, outermost first.
84		opts = append(opts, option.WithMiddleware(SSEFilterMiddleware()))
85		if s := ResolveDebugSink(); s != nil {
86			opts = append(opts, option.WithMiddleware(DebugMiddleware(s)))
87		}
88		if cfg.QuotaHeaderParser != nil && cfg.QuotaSignalObserver != nil {
89			opts = append(opts, option.WithMiddleware(quotaHeaderMiddleware(cfg.QuotaHeaderParser, cfg.QuotaSignalObserver)))
90		}
91		if cfg.RuntimeSignalObserver != nil {
92			opts = append(opts, option.WithMiddleware(runtimeSignalMiddleware(cfg.RuntimeSignalObserver)))
93		}
94	
95		client := oai.NewClient(opts...)
96		return &Client{client: &client, connectTimeout: connectTimeout}
97	}
98	
99	// newHTTPClient returns an *http.Client whose Transport explicitly bounds the
100	// TCP connect phase via net.Dialer.Timeout. The remaining transport knobs
101	// mirror http.DefaultTransport so connection pooling, HTTP/2 negotiation, and
102	// TLS handshake behavior stay identical to stdlib defaults.
103	func newHTTPClient(connectTimeout time.Duration) *http.Client {
104		dialer := &net.Dialer{
105			Timeout:   connectTimeout,
106			KeepAlive: 30 * time.Second,
107		}
108		transport := &http.Transport{
109			Proxy:                 http.ProxyFromEnvironment,
110			DialContext:           dialer.DialContext,
111			ForceAttemptHTTP2:     true,
112			MaxIdleConns:          100,
113			IdleConnTimeout:       90 * time.Second,
114			TLSHandshakeTimeout:   10 * time.Second,
115			ExpectContinueTimeout: 1 * time.Second,
116		}
117		return &http.Client{Transport: transport}
118	}
119	
120	// quotaHeaderMiddleware returns a middleware that runs `parser` on every
121	// response Header and forwards the resulting Signal to `observer`. The
122	// middleware is a no-op when the upstream call returns an error before a
123	// Response is produced, and runs *after* the response has been received but
124	// *before* the SDK consumes its body — both branches still surface the same
125	// (resp, err) tuple to the caller.
126	func quotaHeaderMiddleware(parser func(http.Header, time.Time) quotaheaders.Signal, observer func(quotaheaders.Signal)) option.Middleware {
127		return func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
128			resp, err := next(req)
129			if resp != nil {
130				signal := parser(resp.Header, time.Now())
131				if signal.Present {
132					observer(signal)
133				}
134			}
135			return resp, err
136		}
137	}
138	
139	func runtimeSignalMiddleware(observer func(http.Header, time.Duration, error)) option.Middleware {
140		return func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
141			start := time.Now()
142			resp, err := next(req)
143			if observer != nil {
144				var headers http.Header
145				if resp != nil {
146					headers = resp.Header
147				}
148				observer(headers, time.Since(start), err)
149			}
150			return resp, err
151		}
152	}
