154	// RequestOptions are request controls that map directly to the compatible Chat
155	// Completions wire shape. ExtraOptions carries provider-owned extensions such
156	// as non-standard reasoning/thinking fields.
157	type RequestOptions struct {
158		MaxTokens int
159		// Temperature/TopP/TopK/MinP/RepetitionPenalty are sampling controls.
160		// TopP is OpenAI-standard; TopK / MinP / RepetitionPenalty are
161		// non-standard OpenAI-compat extras that omlx, lmstudio, vLLM, and
162		// llama.cpp accept as top-level body fields. Nil means unset
163		// (server default applies). RepetitionPenalty > 1.0 prevents
164		// exact-token loops.
165		Temperature       *float64
166		TopP              *float64
167		TopK              *int
168		MinP              *float64
169		RepetitionPenalty *float64
170		Seed              int64
171		Stop              []string
172		ExtraOptions      []option.RequestOption
173		// CachePolicy mirrors agent.Options.CachePolicy. The OpenAI-compatible
174		// protocol layer does not act on it today; it is plumbed so a future
175		// caching-aware OpenAI-style provider has a typed field to consume.
176		CachePolicy string
177	}
