190	// CostHook extracts provider-owned cost data from a raw usage object. The SDK
191	// only calls the hook; it does not know provider-specific attribution rules.
192	type CostHook func(rawUsage string) *agent.CostAttribution
193	
194	// StreamAttemptHook builds provider-owned final attempt metadata for a stream.
195	type StreamAttemptHook func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata
196	
