203	// Chat executes one non-streaming Chat Completions request.
204	func (c *Client) Chat(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions) (ChatResult, error) {
205		params := buildParams(model, messages, tools, opts)
206		completion, err := c.client.Chat.Completions.New(ctx, params, opts.ExtraOptions...)
207		if err != nil {
208			return ChatResult{}, err
209		}
210	
211		result := ChatResult{
212			Model:    completion.Model,
213			RawUsage: completion.Usage.RawJSON(),
214		}
215		msgReasoningContent := extractMessageReasoningContent(completion.RawJSON())
216		if completion.Usage.TotalTokens != 0 {
217			result.Usage = tokenUsage(
218				int(completion.Usage.PromptTokens),
219				int(completion.Usage.CompletionTokens),
220				int(completion.Usage.TotalTokens),
221				int(completion.Usage.PromptTokensDetails.CachedTokens),
222			)
223			result.Usage.Reasoning, result.Usage.ReasoningTokensApprox = extractReasoningTokens(result.RawUsage, msgReasoningContent)
224		}
225	
226		if len(completion.Choices) > 0 {
227			choice := completion.Choices[0]
228			result.Content = choice.Message.Content
229			result.FinishReason = string(choice.FinishReason)
230			result.ToolCalls = extractToolCalls(choice.Message.ToolCalls)
231		}
232	
233		return result, nil
234	}
