236	// ChatStream executes one streaming Chat Completions request and converts
237	// chunks into agent stream deltas.
238	func (c *Client) ChatStream(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions, hooks StreamHooks) (<-chan agent.StreamDelta, error) {
239		params := buildParams(model, messages, tools, opts)
240		params.StreamOptions = oai.ChatCompletionStreamOptionsParam{
241			IncludeUsage: oai.Bool(true),
242		}
243	
244		stream := c.client.Chat.Completions.NewStreaming(ctx, params, opts.ExtraOptions...)
245	
246		ch := make(chan agent.StreamDelta, 1)
247		go func() {
248			defer close(ch)
249			send := func(delta agent.StreamDelta) {
250				delta.ArrivedAt = time.Now()
251				ch <- delta
252			}
253	
254			// OpenAI only sends tool call ID in the first chunk for each index;
255			// subsequent argument chunks carry the index but have an empty ID.
256			indexToID := make(map[int]string)
257			responseModel := model
258			var streamCost *agent.CostAttribution
259			var aggReasoningContent strings.Builder
260			for stream.Next() {
261				chunk := stream.Current()
262				if chunk.Model != "" {
263					responseModel = chunk.Model
264				}
265				if hooks.Cost != nil {
266					if cost := hooks.Cost(chunk.Usage.RawJSON()); cost != nil {
267						streamCost = cost
268					}
269				}
270	
271				reasoningContent := extractReasoningContent(chunk.RawJSON())
272				if reasoningContent != "" {
273					aggReasoningContent.WriteString(reasoningContent)
274				}
275	
276				if len(chunk.Choices) > 0 {
277					choice := chunk.Choices[0]
278	
279					for _, tc := range choice.Delta.ToolCalls {
280						id := tc.ID
281						if id != "" {
282							indexToID[int(tc.Index)] = id
283						} else {
284							id = indexToID[int(tc.Index)]
285						}
286						send(agent.StreamDelta{
287							Model:        chunk.Model,
288							ToolCallID:   id,
289							ToolCallName: tc.Function.Name,
290							ToolCallArgs: tc.Function.Arguments,
291						})
292					}
293	
294					if choice.Delta.Content != "" || choice.FinishReason != "" || reasoningContent != "" {
295						send(agent.StreamDelta{
296							Model:            chunk.Model,
297							Content:          choice.Delta.Content,
298							ReasoningContent: reasoningContent,
299							FinishReason:     string(choice.FinishReason),
300						})
301					} else if len(choice.Delta.ToolCalls) == 0 {
302						send(agent.StreamDelta{
303							Model:        chunk.Model,
304							FinishReason: string(choice.FinishReason),
305						})
306					}
307				} else {
308					send(agent.StreamDelta{Model: chunk.Model})
309				}
310	
311				if chunk.Usage.TotalTokens != 0 {
312					usage := tokenUsage(
313						int(chunk.Usage.PromptTokens),
314						int(chunk.Usage.CompletionTokens),
315						int(chunk.Usage.TotalTokens),
316						int(chunk.Usage.PromptTokensDetails.CachedTokens),
317					)
318					usage.Reasoning, usage.ReasoningTokensApprox = extractReasoningTokens(chunk.Usage.RawJSON(), aggReasoningContent.String())
319					send(agent.StreamDelta{Usage: &usage})
320				}
321			}
322	
323			if err := stream.Err(); err != nil {
324				send(agent.StreamDelta{Err: classifyStreamErr(err)})
325				return
326			}
327	
328			done := agent.StreamDelta{
329				Model: responseModel,
330				Done:  true,
331			}
332			if hooks.Attempt != nil {
333				done.Attempt = hooks.Attempt(responseModel, streamCost)
334			}
335			send(done)
336		}()
337	
338		return ch, nil
339	}
