342		params := oai.ChatCompletionNewParams{
343			Model:    model,
344			Messages: convertMessages(messages),
345		}
346		if len(tools) > 0 {
347			params.Tools = convertTools(tools)
348		}
349		if opts.MaxTokens > 0 {
350			params.MaxTokens = oai.Int(int64(opts.MaxTokens))

