501			return *raw.CompletionTokensDetails.ReasoningTokens, false
502		}
503		if raw.ReasoningTokens != nil && *raw.ReasoningTokens > 0 {
504			return *raw.ReasoningTokens, false
505		}
506		// usage path absent; fall back to reasoning_content char-count estimate.
507		if reasoningContent != "" {
508			return len(reasoningContent) / 4, true
509		}
510		return 0, false
511	}
