513	// extractMessageReasoningContent reads choices[0].message.reasoning_content
514	// from a full (non-streaming) Chat Completions response JSON. Providers that
515	// do thinking inline but do not populate completion_tokens_details (e.g. ds4)
516	// carry the thinking text here. Returns "" when absent or unparseable.
517	func extractMessageReasoningContent(rawCompletionJSON string) string {
518		if rawCompletionJSON == "" {
519			return ""
520		}
521		var raw struct {
522			Choices []struct {
523				Message struct {
524					ReasoningContent string `json:"reasoning_content"`
525				} `json:"message"`
526			} `json:"choices"`
527		}
528		if err := json.Unmarshal([]byte(rawCompletionJSON), &raw); err != nil || len(raw.Choices) == 0 {
529			return ""
530		}
531		return raw.Choices[0].Message.ReasoningContent
532	}
