32	// when no source reported a token count, while still returning warnings for
33	// malformed sources or source disagreements.
34	func ResolveFinalUsage(candidates []UsageCandidate) (*FinalUsage, []FinalWarning) {
35		if len(candidates) == 0 {
36			return nil, nil
37		}
38		ordered := append([]UsageCandidate(nil), candidates...)
39		sort.SliceStable(ordered, func(i, j int) bool {
40			return usageSourceRank(ordered[i].Source) < usageSourceRank(ordered[j].Source)
41		})
42	
43		var warnings []FinalWarning
44		var valid []UsageCandidate
45		validBySource := map[string]int{}
46		for _, candidate := range ordered {
47			if candidate.Counts.Any() {
48				if idx, ok := validBySource[candidate.Source]; ok {
49					valid[idx] = candidate
50				} else {
51					validBySource[candidate.Source] = len(valid)
52					valid = append(valid, candidate)
53				}
54			}
55			if candidate.Warning != "" {
56				warnings = append(warnings, FinalWarning{
57					Code:    UsageWarningMalformed,
58					Message: candidate.Warning,
59					Sources: []UsageSourceEvidence{
60						usageEvidence(candidate),
61					},
62				})
63			}
64		}
65		if len(valid) == 0 {
66			return nil, warnings
67		}
68	
69		chosen := valid[0]
70		for i := 1; i < len(valid); i++ {
71			if usageCountsDisagree(chosen.Counts, valid[i].Counts) {
72				warnings = append(warnings, FinalWarning{
73					Code:    UsageWarningDisagreement,
74					Message: "token usage sources disagree; selected source by documented precedence",
75					Sources: []UsageSourceEvidence{
76						usageEvidence(chosen),
77						usageEvidence(valid[i]),
78					},
79				})
80			}
81		}
82	
83		usage := &FinalUsage{
84			InputTokens:      chosen.Counts.InputTokens,
85			OutputTokens:     chosen.Counts.OutputTokens,
86			CacheReadTokens:  chosen.Counts.CacheReadTokens,
87			CacheWriteTokens: chosen.Counts.CacheWriteTokens,
88			CacheTokens:      chosen.Counts.CacheTokens,
89			ReasoningTokens:  chosen.Counts.ReasoningTokens,
90			TotalTokens:      chosen.Counts.TotalTokens,
91			Source:           chosen.Source,
92			Fresh:            chosen.Fresh,
93			CapturedAt:       chosen.CapturedAt,
94			Sources:          make([]UsageSourceEvidence, 0, len(valid)),
95		}
96		for _, candidate := range valid {
97			usage.Sources = append(usage.Sources, usageEvidence(candidate))
98		}
99		return usage, warnings
