// applyReasoningTokenFallback derives the reasoning token count from
// ReasoningContent when the usage block omits it.
// When ReasoningTokens is absent or zero AND ReasoningContent is non-empty,
// counts the tokens in the content using the compaction estimator.
// When ReasoningTokens is already present (non-zero or explicit zero),
// it takes precedence and is not overwritten.
func applyReasoningTokenFallback(counts *UsageTokenCounts, reasoningContent string) {
	if reasoningContent == "" {
		return
	}
	if counts.ReasoningTokens != nil && *counts.ReasoningTokens > 0 {
		return
	}
	if counts.ReasoningTokens != nil && *counts.ReasoningTokens == 0 {
		return
	}
	estimatedTokens := compaction.EstimateTokens(reasoningContent)
	counts.ReasoningTokens = &estimatedTokens
}

func usageSourceRank(source string) int {
	switch source {
	case UsageSourceNativeStream:
		return 0
	case UsageSourceNativeTokenCount:
		return 1
	case UsageSourceTranscript:
		return 2
	case UsageSourceStatusOutput:
		return 3
	case UsageSourceFallback:
		return 4
	default:
		return 100
	}
}

