func TestReasoningTokens_FallbackFromContent(t *testing.T) {
	tests := []struct {
		name            string
		candidates      []UsageCandidate
		wantReasoningTk int
		wantNil         bool
		label           string
	}{
		{
			name: "usage_present_reasoning_tokens",
			candidates: []UsageCandidate{
				{
					Source:           UsageSourceNativeStream,
					Counts:           UsageTokenCounts{ReasoningTokens: IntPtr(100)},
					ReasoningContent: "this is 20 characters",
				},
			},
			wantReasoningTk: 100,
			wantNil:         false,
			label:           "usage wins over content",
		},
		{
			name: "usage_absent_content_present",
			candidates: []UsageCandidate{
				{
					Source: UsageSourceNativeStream,
					Counts: UsageTokenCounts{InputTokens: IntPtr(10), OutputTokens: IntPtr(5)},
					ReasoningContent: "0123456789" + "0123456789" + "0123456789" + "012",
				},
			},
			wantReasoningTk: 8,
			wantNil:         false,
			label:           "fallback from content (32 chars / 4 = 8 tokens)",
		},
		{
			name: "both_absent",
			candidates: []UsageCandidate{
				{
					Source:           UsageSourceNativeStream,
					Counts:           UsageTokenCounts{InputTokens: IntPtr(10), OutputTokens: IntPtr(5)},
					ReasoningContent: "",
				},
			},
			wantNil: true,
			label:   "no usage, no content",
		},
		{
			name: "usage_explicit_zero_content_present",
			candidates: []UsageCandidate{
				{
					Source:           UsageSourceNativeStream,
					Counts:           UsageTokenCounts{ReasoningTokens: IntPtr(0)},
					ReasoningContent: "some thinking content here",
				},
			},
			wantReasoningTk: 0,
			wantNil:         false,
			label:           "explicit zero from usage, do not fall back",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			usage, _ := ResolveFinalUsage(tt.candidates)
			if tt.wantNil {
				if usage != nil {
					t.Fatalf("%s: expected nil usage, got %#v", tt.label, usage)
				}
				return
			}
			if usage == nil {
				t.Fatalf("%s: expected usage, got nil", tt.label)
			}
			if usage.ReasoningTokens == nil {
				t.Fatalf("%s: ReasoningTokens should not be nil, got %#v", tt.label, usage.ReasoningTokens)
			}
			if *usage.ReasoningTokens != tt.wantReasoningTk {
				t.Fatalf("%s: got %d reasoning tokens, want %d", tt.label, *usage.ReasoningTokens, tt.wantReasoningTk)
			}
		})
	}
}

